import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/users")
public class UserSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserSearchServlet.class.getName());

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("DB_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String department = req.getParameter("dept");
        String role = req.getParameter("role");
        String sortBy = req.getParameter("sort");
        String authToken = req.getHeader("X-Internal-Auth");

        // Validate auth token presence
        if (authToken == null || authToken.isEmpty()) {
            resp.sendError(401, "Missing authentication");
            return;
        }

        // Basic input length check
        if (department != null && department.length() > 100) {
            resp.sendError(400, "Parameter too long");
            return;
        }

        // Build query - sort column validated against allowlist
        String orderClause = "name";
        if ("email".equals(sortBy) || "hire_date".equals(sortBy) || "name".equals(sortBy)) {
            orderClause = sortBy;
        }

        StringBuilder sql = new StringBuilder(
            "SELECT id, name, email, department, role FROM employees WHERE active = 1"
        );

        // Department filter - VULNERABLE: string concatenation
        if (department != null && !department.isEmpty()) {
            sql.append(" AND department = '" + department + "'");
        }

        // Role filter - also concatenated
        if (role != null && !role.isEmpty()) {
            sql.append(" AND role = '" + role + "'");
        }

        sql.append(" ORDER BY " + orderClause + " LIMIT 50");

        log.info("Executing query for dept=" + department + " role=" + role);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql.toString())) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                first = false;
                json.append(String.format(
                    "  {\"id\": %d, \"name\": \"%s\", \"email\": \"%s\", \"dept\": \"%s\", \"role\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("name").replace("\"", "\\\""),
                    rs.getString("email").replace("\"", "\\\""),
                    rs.getString("department").replace("\"", "\\\""),
                    rs.getString("role").replace("\"", "\\\"")
                ));
            }

            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
